bg=3
patterns={
 5:[[1,1,0],[0,1,0],[0,1,1]],
 7:[[1,1,1],[1,0,1],[0,1,0]],
 6:[[1,1,0],[0,1,0],[1,1,1]],
 9:[[1,1,1],[0,1,0],[1,0,1]],
 4:[[1,0,0],[0,1,1],[1,0,0]],
 2:[[1,0,0],[0,1,1],[0,0,1]],
}
def make_panel(color):
    src=patterns[color]
    return [[color]*5] + [[color]+[bg if x else color for x in row]+[color] for row in src] + [[color]*5]
# Wait middle rows should be inverted occupancy, as constructed: source 1->bg, source 0->color.
panels={c:make_panel(c) for c in patterns}
rows=[[bg]*13]
for left,right in [(5,7),(6,9),(4,2)]:
    for i in range(5):
        rows.append([bg]+panels[left][i]+[bg]+panels[right][i]+[bg])
    if left!=4: rows.append([bg]*13)
rows.append([bg]*13)
print(len(rows), [len(x) for x in rows])
import json
print(json.dumps(rows))
